// Refactored Express application with environment-based configuration
// All hardcoded values moved to environment variables

require('dotenv').config(); // Load environment variables from .env file

const express = require('express');
const app = express();

// ============================================
// ENVIRONMENT CONFIGURATION & VALIDATION
// ============================================

// Validate required environment variables
const validateEnv = () => {
  const required = ['NODE_ENV'];
  const missing = required.filter(key => !process.env[key]);

  if (missing.length > 0) {
    throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
  }
};

// Configuration object with defaults and type coercion
const config = {
  // Server configuration
  port: parseInt(process.env.PORT, 10) || 3000,
  nodeEnv: process.env.NODE_ENV || 'development',
  isProduction: process.env.NODE_ENV === 'production',
  isDevelopment: process.env.NODE_ENV !== 'production',
  isTest: process.env.NODE_ENV === 'test',

  // Health check configuration
  healthStatus: process.env.HEALTH_STATUS || 'ok',

  // User data configuration
  userDataSource: process.env.USER_DATA_SOURCE || 'database', // 'database', 'mock', 'file'
  mockDataFile: process.env.MOCK_USER_DATA_FILE || './mock-data/test-users.json',
};

// Validate environment on startup
try {
  validateEnv();
  console.log(`Environment validated: ${config.nodeEnv}`);
} catch (error) {
  console.error('Environment validation failed:', error.message);
  process.exit(1);
}

// ============================================
// USER DATA MANAGEMENT
// ============================================

// Mock user data (only for development/testing)
const mockUsers = [
  { id: 1, name: 'Alice', email: 'alice@dev.local' },
  { id: 2, name: 'Bob', email: 'bob@dev.local' },
];

// User data source factory
const getUserDataSource = () => {
  switch (config.userDataSource) {
    case 'mock':
      return {
        getAllUsers: async () => mockUsers,
      };

    case 'file':
      try {
        const fs = require('fs');
