// Secure application configuration using environment variables
// Addresses all hardcoded value vulnerabilities

require('dotenv').config();
const express = require('express');
const app = express();

// ==================== ENVIRONMENT-DRIVEN CONFIGURATION ====================

// Server Configuration
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';
const NODE_ENV = process.env.NODE_ENV || 'development';
const isProduction = NODE_ENV === 'production';
const isDevelopment = NODE_ENV === 'development';
const isTest = NODE_ENV === 'test';

// Security Configuration
const ALLOWED_ORIGINS = process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'];
const RATE_LIMIT_WINDOW_MS = parseInt(process.env.RATE_LIMIT_WINDOW_MS) || 15 * 60 * 1000;
const RATE_LIMIT_MAX_REQUESTS = parseInt(process.env.RATE_LIMIT_MAX_REQUESTS) || 100;
const MAX_BODY_SIZE = process.env.MAX_BODY_SIZE || '10kb';

// Feature Flags
const ENABLE_HEALTH_CHECK = process.env.ENABLE_HEALTH_CHECK !== 'false';
const ENABLE_USER_ENDPOINT = process.env.ENABLE_USER_ENDPOINT !== 'false';
const ENABLE_METRICS = process.env.ENABLE_METRICS === 'true';

// ==================== MOCK DATA CONFIGURATION ====================

// Load mock data from environment or use defaults only in non-production
let mockUsers = [];
if (!isProduction) {
  try {
    const usersFromEnv = process.env.TEST_USERS_DATA;
    if (usersFromEnv) {
      mockUsers = JSON.parse(usersFromEnv);
    } else {
      // Fallback mock data - should only use in development/testing
      mockUsers = JSON.parse(process.env.MOCK_USERS || JSON.stringify([
        { id: 'mock-1', name: 'Alice', email: 'alice@example.com', _mock: true },
        { id: 'mock-2', name: 'Bob', email: 'bob@example.com', _mock: true },
      ]));
    }
  } catch (error) {
    console.error('Error loading mock users:', error.message);
    mockUsers = [];
  }
}

// ==================== MIDDLEWARE CONFIGURATION ====================

// Security headers (Helmet)
const helmet = require('helmet');
app.use(helmet({
  hsts: isProduction, // Enable HSTS only in production
  contentSecurityPolicy: isProduction ? undefined : false, // CSP config for production
}));

// CORS configuration
const cors = require('cors');
app.use(cors({
  origin: ALLOWED_ORIGINS,
  credentials: true
}));

// Rate limiting
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: RATE_LIMIT_WINDOW_MS,
  max: RATE_LIMIT_MAX_REQUESTS,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Request logging (combined in production, dev in development)
const morgan = require('morgan');
app.use(morgan(isProduction ? 'combined' : 'dev'));

// Body parser with size limits
app.use(express.json({ limit: MAX_BODY_SIZE }));
app.use(express.urlencoded({ limit: MAX_BODY_SIZE, extended: true }));

// ==================== REQUEST VALIDATION ====================

const { body, param, query, validationResult } = require('express-validator');

// Generic validation error handler
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  next();
};

// ==================== ROUTES ====================

// Health check endpoint
if (ENABLE_HEALTH_CHECK) {
  app.get('/health', (req, res) => {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      environment: NODE_ENV,
      version: process.env.API_VERSION || '1.0.0'
    });
  });
}

// User information endpoint (only if enabled and not production)
if (ENABLE_USER_ENDPOINT) {
  const userValidation = [
    query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
    query('offset').optional().isInt({ min: 0 }).toInt(),
    handleValidationErrors
  ];

  app.get('/users', userValidation, (req, res) => {
    if (isProduction && mockUsers.length === 0) {
      return res.status(404).json({ error: 'No user data available' });
    }

    const limit = req.query.limit || 10;
    const offset = req.query.offset || 0;

    const paginatedUsers = mockUsers.slice(offset, offset + limit);

    // Remove mock flags from response
    const sanitizedUsers = paginatedUsers.map(({ _mock, ...user }) => user);

    res.json({
      data: sanitizedUsers,
      meta: {
        total: mockUsers.length,
        limit,
        offset,
        hasMore: offset + limit < mockUsers.length
      }
    });
  });
}

// Metrics/Stats endpoint (requires env flag)
if (ENABLE_METRICS) {
  app.get('/metrics', (req, res) => {
    res.json({
      uptime: process.uptime(),
      memory: process.memoryUsage(),
      environment: NODE_ENV,
      timestamp: new Date().toISOString()
    });
  });
}

// ==================== ERROR HANDLING ====================

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString()
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Error:', err.message);

  // Send different error details based on environment
  const errorResponse = {
    error: 'Internal Server Error',
    timestamp: new Date().toISOString()
  };

  if (!isProduction) {
    errorResponse.details = err.message;
    errorResponse.stack = err.stack;
  }

  res.status(err.status || 500).json(errorResponse);
});

// ==================== SERVER START ====================

if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on ${HOST}:${PORT}`);
    console.log(`Environment: ${NODE_ENV}`);
    console.log(`Node version: ${process.version}`);
    console.log(`PID: ${process.pid}`);

    if (!isProduction) {
      console.log('⚠️  WARNING: Running in non-production mode');
      console.log('Mock data and debug endpoints may be accessible');
    }
  });
}

module.exports = app;

