## ✅ **Recommended Fixes for `app.js`**

Here's the secure version with proper environment variable usage:

```javascript
require('dotenv').config(); // Load env vars from .env file

const express = require('express');
const app = express();

// Environment variables with defaults
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

app.get('/health', (req, res) => {
  const HEALTH_STATUS = process.env.HEALTH_STATUS || 'ok';
  res.json({ 
    status: HEALTH_STATUS, 
    timestamp: new Date().toISOString(),
    environment: NODE_ENV
  });
});

app.get('/users', (req, res) => {
  if (process.env.NODE_ENV === 'production') {
    // TODO: Connect to database and fetch real users
    res.status(501).json({ error: 'Database not configured' });
  } else {
    // Mock data for development only
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  }
});

app.listen(PORT, () => {
  console.log(`[${NODE_ENV}] Server running on port ${PORT}`);
});

module.exports = app;
```

